use std::collections::HashSet;

/// Removes duplicates from the input vector,
/// preserving the original order of first occurrences.
///
/// Postconditions:
/// 1. The output contains no duplicates.
/// 2. The set of output elements equals the set of input elements.
///
/// # Arguments
/// * `nums` - Vector of i32 integers, possibly empty, possibly with duplicates.
///
/// # Returns
/// A `Vec<i32>` containing each element from `nums` exactly once,
/// in the order they first appeared.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for &num in &nums {
        if !seen.contains(&num) {
            seen.insert(num);
            result.push(num);
        }
    }

    result
}